{
  "project_id": "9fba7b4aa94546dcbb0a",
  "name": "create_user_settings_key_value_store",
  "query": "create table public.user_settings (
  user_id uuid not null references auth.users (id) on delete cascade,
  key text not null check (length(trim(key)) > 0),
  value jsonb not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (user_id, key)
);

comment on table public.user_settings is 'Per-user settings stored as key-value pairs.';
comment on column public.user_settings.value is 'JSON value for the setting, allowing strings, numbers, booleans, arrays, and objects.';

create index user_settings_user_id_idx on public.user_settings (user_id);

alter table public.user_settings enable row level security;

create policy "Users can view their own settings"
on public.user_settings
for select
to authenticated
using ((select auth.uid()) = user_id);

create policy "Users can insert their own settings"
on public.user_settings
for insert
to authenticated
with check ((select auth.uid()) = user_id);

create policy "Users can update their own settings"
on public.user_settings
for update
to authenticated
using ((select auth.uid()) = user_id)
with check ((select auth.uid()) = user_id);

create policy "Users can delete their own settings"
on public.user_settings
for delete
to authenticated
using ((select auth.uid()) = user_id);

grant select, insert, update, delete on table public.user_settings to authenticated;
grant all on table public.user_settings to service_role;"
}

